// A class adhering to the Rule of Five
class Base {
public:
  // 1. User-declared virtual destructor
  virtual ~Base() = default;

  // Because a dtor was declared, moves would be suppressed.
  // We explicitly default them to re-enable moving.
  // 2. Move Constructor
  Base(Base&&) = default;
  // 3. Move Assignment Operator
  Base& operator=(Base&&) = default;

  // Declaring move operations suppresses copy operations.
  // We explicitly default them to re-enable copying.
  // 4. Copy Constructor
  Base(const Base&) = default;
  // 5. Copy Assignment Operator
  Base& operator=(const Base&) = default;
};
